mapper.update:
UPDATE aircas_dataset
count = #{count},
data_type = #{dataType},
update_time = now(), update_by = #{updateBy}
and base_dataset_id = #{baseDatasetId}

mapper.select:
SELECT
	ad.dataset_id,ad.base_dataset_id,ad.dataset_name,ad.progress,ad.count,ad.data_type,
	ad.size,ad.create_time,ad.update_time,ad.create_by,ad.update_by,ad.version,
	ad.label_type,ad.first_picture,ad.label_json
FROM
	aircas_dataset ad

	ad.del_flag = '0'


		AND ad.dataset_name LIKE #{datasetNameLike}


		AND ad.base_dataset_id = #{query.baseDatasetId}


		AND ad.data_type = #{query.dataType}


		AND ad.version = #{query.version}


		AND ad.label_type = #{query.labelType}




	ORDER BY ad.create_time DESC
